const music=new Audio('assets/audio/ciabatta-song.mp3');music.id='background-music';music.hidden=true;document.body.append(music);music.loop=true;music.volume=.24;music.preload='none';let musicEnabled=false;
function syncMusic(){if(!musicEnabled||document.hidden||state.phase!=='playing'&&state.phase!=='serving'){music.pause();return;}music.play().catch(error=>{if(error.name==='AbortError')return;sound=false;musicEnabled=false;effects.setEnabled(false);updateSound();notify('השמע לא התחיל. לחצו שוב על כפתור השמע.');});}


