FOODS.forEach((food,i)=>{const b=document.createElement('button');b.className='ingredient';b.dataset.index=i;b.setAttribute('aria-label',`הוספת מנה אחת של ${food.name}`);b.innerHTML=`<span class="stock-label"></span><span class="keyhint" aria-hidden="true">${i+1}</span><span class="ingredient-counter" aria-hidden="true"></span><span class="food-art food-${i}" aria-hidden="true"></span><span class="ingredient-name">${food.name}</span>`;b.addEventListener('click',()=>addFood(i));$('ingredients').append(b);});
function refill(){if(!requestRefill(state)){notify(state.refillRemaining>0?'ניצן כבר בדרך עם הארגז.':'כל המגשים מלאים.');return false;}effects.play('refill-start');renderStock();notify('ניצן: מי גמר את הפסטו? טוב, אני מביא.');return true;}
function renderStock(){document.querySelectorAll('.ingredient').forEach((b,i)=>{b.querySelector('.stock-label').textContent='נותרו '+state.stock[i];b.classList.toggle('stock-low',state.stock[i]<=2);b.classList.toggle('stock-empty',state.stock[i]===0);b.setAttribute('aria-label',`הוספת מנה אחת של ${foodLabel(i)}, נותרו ${state.stock[i]}`);});$('refill').disabled=state.phase!=='playing'||state.refillRemaining>0;$('refill').classList.toggle('refilling',state.refillRemaining>0);$('refill').classList.toggle('needed',state.stock.some(n=>n<=2));const line=state.refillRemaining>0?'מגיע בעוד '+Math.ceil(state.refillRemaining)+' שניות':state.stock.every(n=>n===STOCK_CAPACITY)?'ניצן · הכול מלא':'ניצן · לחצו למילוי';if($('refill-label').textContent!==line)$('refill-label').textContent=line;}
function pickBread(){if(!takeBread(state))return false;effects.play('bread');render();notify('הצ׳אבטה מוכנה. עכשיו לוחצים על התוספות לפי הבון.');return true;}
function addFood(i){if(state.phase==='playing'&&state.stock[i]===0){notify('המגש ריק. לחצו על ניצן כדי למלא את התוספות.','error');return false;}if(state.phase==='playing'&&!state.breadTaken){notify('קודם לוחצים על הצ׳אבטה הריקה שבצד.','error');return false;}if(!add(state,i)){if(state.phase==='playing')notify('אין עוד מקום בצ׳אבטה. אפשר להסיר את התוספת האחרונה.','error');return false;}effects.play(FOODS[i].id);render();const c=counts(state);if(c[i]>state.recipe[i])notify(`${foodLabel(i)} מעבר להזמנה. אפשר להסיר את התוספת האחרונה.`,'error');else if(matches(state))notify('בדיוק כמו בהזמנה. אפשר להגיש!','success');else notify(`נוספה מנה של ${foodLabel(i)}.`);return true;}
function removeLast(){const removed=undo(state);if(removed===null)return false;effects.play('undo');render();notify(`הוסרה המנה האחרונה של ${foodLabel(removed)}.`);return true;}
function deliver(){if(state.phase!=='playing')return false;if(!state.breadTaken){notify('קודם לוקחים צ׳אבטה בלחיצה על הלחם.','error');return false;}const reward=serve(state);if(reward===null){const c=counts(state),excess=FOODS.filter((_,i)=>c[i]>state.recipe[i]).map(f=>f.name),missing=FOODS.filter((_,i)=>c[i]<state.recipe[i]).map(f=>f.name);notify(excess.length?`יש תוספות מיותרות: ${excess.join(', ')}. הסירו וחזרו להזמנה.`:`עוד חסר: ${missing.join(', ')}.`,'error');$('board').classList.remove('shake');void $('board').offsetWidth;$('board').classList.add('shake');return false;}tone(true);render();$('board').classList.add('serving');$('customer').classList.add('leaving');$('score').classList.add('score-pop');notify(`בול! עוד ${reward} נקודות${state.lastTreatBonus?' · כולל 20 על הפינוק של אורי!':'.'}`,'success');pendingNext=setTimeout(()=>{next(state);$('board').classList.remove('serving');$('customer').classList.remove('leaving');$('score').classList.remove('score-pop');render();notify('הזמנה חדשה! שימו לב לכמויות ולשעון.');pendingNext=null;if(document.hidden)pause('pause');},2200);return true;}
function renderGuests(){const waiting=state.waiting;$('second-customer').hidden=!waiting;if(waiting){const person=customerForOrder(waiting.order);$('second-image').src=person.image;$('second-image').alt=person.name;$('second-label').textContent=person.name+' · להחלפת הזמנה';$('second-timer').textContent=Math.ceil(waiting.remaining)+' שניות';$('second-customer').disabled=state.phase!=='playing';}$('kombucha').disabled=!canTreat(state);$('kombucha').classList.toggle('available',canTreat(state));$('kombucha-label').textContent=state.treat?(state.phase==='serving'?'קמבוצ׳ה על הבית!':'פינוק מוכן · להגיש בזמן!'):canTreat(state)?'פנקו בקמבוצ׳ה · +20':'קמבוצ׳ה · יעד '+(Number.isFinite(state.duration)?Math.floor(state.duration/2)+' שנ׳':'מהזמנה 2');}
$('second-customer').onclick=()=>{if(switchCustomer(state)){render();notify('עברנו להזמנה של '+customerForOrder(state.order).name+'. ההכנה הקודמת נשמרה.');}};
$('kombucha').onclick=()=>{if(offerTreat(state)){effects.play('kombucha');render();notify('אורי: קמבוצ׳ה מותססת על הבית! הגישו לפני חצי הזמן לבונוס 20.','success');}};
function render(){const person=customerForOrder(state.order);if($('customer').getAttribute('src')!==person.image)$('customer').src=person.image;$('customer').alt='הדמות של '+person.name;$('serve').setAttribute('aria-label','הגשת הצ׳אבטה ל'+person.name);$('customer-name').textContent=person.name;renderSpeech();const c=counts(state);$('score').textContent=state.score;$('order-number').textContent=`הזמנה ${String(state.order).padStart(2,'0')}`;$('order-badge').textContent=state.order===1?'בלי לחץ':'טרי, ומהר';$('order-title').textContent=state.phase==='serving'?'תודה רבה!':'צ׳אבטה';$('order-items').replaceChildren();state.recipe.forEach((qty,i)=>{if(!qty)return;const el=document.createElement('div');el.className='order-item'+(c[i]===qty?' complete':c[i]>qty?' extra':'');el.setAttribute('aria-label',`${foodLabel(i)}: ${c[i]} מתוך ${qty}`);el.innerHTML=`<b>${qty}</b><span>${foodLabel(i)}</span><span class="receipt-check">${c[i]===qty?"✓":c[i]?c[i]+"/"+qty:""}</span>`;$('order-items').append(el);});$('meal-count').textContent=!state.breadTaken?'לחצו על הלחם כדי לקחת צ׳אבטה':matches(state)?'מוכנה! לחצו על הלקוח להגשה':'מוסיפים לפי הבון';$('board').classList.toggle('taken',state.breadTaken);$('board').disabled=state.phase!=='playing'||state.breadTaken;$('board-stamp').textContent=state.breadTaken?'הצ׳אבטה שלכם':'צ׳אבטה ריקה';$('meal-list').replaceChildren();if(!state.meal.length)$('meal-list').textContent='בחרו תוספת כדי להתחיל';c.forEach((n,i)=>{if(!n)return;const chip=document.createElement('span');chip.className='meal-chip'+(n>state.recipe[i]?' wrong':'');chip.textContent=`${foodLabel(i)} × ${n}`;$('meal-list').append(chip);});$('toppings').replaceChildren();state.meal.forEach((i,index)=>{const el=document.createElement('span');el.className=`topping food-art food-${i}`;el.style.transform=`translate(${((index%3)-1)*24}px,${-Math.floor(index/3)*3}px) rotate(${((index%3)-1)*8}deg)`;if(index<state.meal.length-1)el.style.animation='none';$('toppings').append(el);});document.querySelectorAll('.ingredient').forEach((button,i)=>{button.querySelector('.ingredient-counter').textContent=c[i]||'';button.disabled=state.phase!=='playing';});$('undo').disabled=!state.meal.length||state.phase!=='playing';$('serve').disabled=state.phase!=='playing';$('serve').classList.toggle('ready',state.breadTaken&&matches(state));$('pause').disabled=state.phase!=='playing';renderStock();renderTimer();}
function renderSpeech(){const p=customerForOrder(state.order);const line=state.phase==='serving'?p.served:state.remaining<state.duration*.5?p.waiting:p.entry;if($('customer-line').textContent!==line)$('customer-line').textContent=line;}
function renderTimer(){renderGuests();renderSpeech();const infinite=!Number.isFinite(state.remaining);$('timer').textContent=infinite?'∞':Math.ceil(state.remaining)+'″';$('time-label').textContent=infinite?'בהזמנה הראשונה אין לחץ':state.remaining<15?'הבטן כבר מקרקרת…':'סבלנות';const percent=infinite?100:100*state.remaining/state.duration;$('patience').style.width=percent+'%';$('patience').classList.toggle('urgent',percent<25);document.querySelector('.patience-track').setAttribute('aria-valuenow',String(Math.round(percent)));}
function showDialog(mode){state.dialog=mode;const story=mode==='story';$('opening-story').hidden=!story;$('standard-dialog').hidden=story;$('overlay').classList.toggle('story-mode',story);$('overlay').setAttribute('aria-labelledby',story?'story-title':'dialog-title');if(story){$('game').classList.add('paused');if(!$('overlay').open)$('overlay').showModal();return;}const settings={intro:['ברוכים הבאים לדוכן','הצ׳אבטה הראשונה עליכם.','קוראים את הבון, לוחצים על הצ׳אבטה הריקה ואז על התוספות. להגשה לוחצים על הלקוח. אפשר להסיר את התוספת האחרונה ליד הלחם. כשהמלאי יורד, לוחצים על ניצן למילוי.','פותחים את הדוכן','הראשונה בלי שעון. מהזמנה 4: שני לקוחות. פינוק קמבוצ׳ה בהגשה עד חצי הזמן = עוד 20 נקודות.'],pause:['הדוכן בהפסקה','קחו רגע, אנחנו מחכים.','ההזמנה והצ׳אבטה נשמרו. השעון עצור עד שחוזרים.','חוזרים לדוכן',''],help:['המתכון להצלחה','קוראים. מרכיבים. מגישים.','תחילה לוחצים על הלחם. כל לחיצה על אוכל מוסיפה מנה אחת; הכמות הדרושה כתובה בבון. מתקנים בכפתור שליד הלחם, ומגישים בלחיצה על הלקוח. בכל מגש יש 8 מנות; לחיצה על ניצן תמלא את כל המגשים אחרי כמה שניות. ההסרה מחזירה מנה למלאי. מההזמנה הרביעית מחכים שני לקוחות עם שעונים נפרדים. לחצו על הלקוח הקטן להחלפת הזמנה; ההכנה נשמרת. הכינו מנה במחצית הראשונה של הזמן, לחצו על הקמבוצ׳ה והגישו בזמן לקבלת 20 נקודות נוספות.','הבנתי, חוזרים','במחשב: B ללקיחת לחם, מקשים 1–6 לתוספות, Backspace להסרה ו־Enter להגשה.'],over:['נגמרה הסבלנות','סוגרים לרגע את הדוכן.',`הגשתם ${state.served} צ׳אבטות וצברתם ${state.score} נקודות. מתחילים שוב?`,'עוד סיבוב','כל סיבוב מתחיל בהזמנה בלי שעון.']};const a=settings[mode];$('dialog-eyebrow').textContent=a[0];$('dialog-title').textContent=a[1];$('dialog-text').textContent=a[2];$('dialog-action').textContent=a[3];$('dialog-note').textContent=a[4];$('instructions').hidden=mode!=='intro';$('game').classList.add('paused');if(!$('overlay').open)$('overlay').showModal();}
function pause(mode){if(state.phase!=='playing')return;state.phase='paused';syncMusic();showDialog(mode);render();}
function closeDialog(){if(state.dialog==='story'){showDialog('intro');$('dialog-action').focus();return;}if(!assetsReady)return;const mode=state.dialog;if(mode==='intro'||mode==='over'){state=createState();state.phase='playing';}else state.phase='playing';state.dialog=null;$('overlay').close();$('game').classList.remove('paused');lastTime=performance.now();render();syncMusic();if(mode==='intro'||mode==='over')notify('קודם לוחצים על הצ׳אבטה הריקה שבצד.');}
$('story-next').onclick=closeDialog;$('refill').onclick=refill;$('board').onclick=pickBread;$('undo').onclick=removeLast;$('serve').onclick=deliver;$('pause').onclick=()=>pause('pause');$('help').onclick=()=>pause('help');$('sound').onclick=()=>{sound=effects.setEnabled(!sound);musicEnabled=sound;updateSound();syncMusic();tone();};$('dialog-action').onclick=closeDialog;$('overlay').addEventListener('cancel',e=>{e.preventDefault();if(state.dialog==='pause'||state.dialog==='help')closeDialog();});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause('pause');syncMusic();lastTime=performance.now();});window.addEventListener('keydown',e=>{if(e.target instanceof HTMLButtonElement&&(e.key==='Enter'||e.key===' '))return;if(e.ctrlKey||e.metaKey||e.altKey||state.phase!=='playing')return;if(e.key.toLowerCase()==='b'){e.preventDefault();pickBread();}else if(/^[1-6]$/.test(e.key)){e.preventDefault();addFood(Number(e.key)-1);}else if(e.key==='Backspace'){e.preventDefault();removeLast();}else if(e.key==='Enter'){e.preventDefault();deliver();}else if(e.key==='Escape'||e.key===' '){e.preventDefault();pause('pause');}});
function frame(now){const seconds=(now-lastTime)/1000;lastTime=now;const prev=state.phase,wasRefilling=state.refillRemaining>0;tick(state,seconds);if(wasRefilling){renderStock();if(state.refillRemaining===0){effects.play('refill-done');notify('ניצן: המגשים מלאים. תנו עבודה!','success');}}if(prev==='playing'&&state.phase==='over'){syncMusic();render();showDialog('over');}else if(state.phase==='playing')renderTimer();requestAnimationFrame(frame);}updateSound();render();showDialog('story');$('dialog-action').disabled=true;$('dialog-action').textContent='מכינים את הדוכן…';const assets=['background.png','uri.png','foods.png','empty-bread.png','nitzan.png','kombucha.png',...CUSTOMERS.map(p=>p.id+'.png')];Promise.all(assets.map(name=>new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src='assets/'+name;}))).then(()=>{assetsReady=true;$('dialog-action').disabled=false;$('dialog-action').textContent='פותחים את הדוכן';}).catch(()=>{$('dialog-text').textContent='חלק מהאיורים לא נטענו. בדקו את החיבור ונסו שוב.';$('dialog-action').disabled=false;$('dialog-action').textContent='לנסות שוב';$('dialog-action').onclick=()=>location.reload();});requestAnimationFrame(frame);
// Optional WebMCP: same actions and state as the visible controls; no background gameplay.
const context=document.modelContext;
if(context?.registerTool){const controller=new AbortController();const snapshot=()=>({customer:customerForOrder(state.order).name,customerLine:$('customer-line').textContent,phase:state.phase,waiting:state.waiting,treatAvailable:canTreat(state),stock:Object.fromEntries(FOODS.map((f,i)=>[f.id,state.stock[i]])),refillRemaining:Math.ceil(state.refillRemaining),breadTaken:state.breadTaken,order:state.order,score:state.score,recipe:Object.fromEntries(FOODS.map((f,i)=>[f.id,state.recipe[i]])),prepared:Object.fromEntries(FOODS.map((f,i)=>[f.id,counts(state)[i]])),remaining:Number.isFinite(state.remaining)?Math.ceil(state.remaining):null});const tool={name:'ciabatta_game',description:'Read the game, start or resume a round, take an empty ciabatta first, add one ingredient portion, undo the last portion, submit the prepared ciabatta, or ask Nitzan to refill all ingredient trays. Uses the visible game state.',annotations:{readOnlyHint:false,untrustedContentHint:false},inputSchema:{type:'object',properties:{action:{type:'string',enum:['read','start','take_bread','add','undo','serve','refill','switch_customer','treat']},ingredient:{type:'string',enum:FOODS.map(f=>f.id)}},required:['action'],additionalProperties:false},execute(input){if(!input||!['read','start','take_bread','add','undo','serve','refill','switch_customer','treat'].includes(input.action))throw new Error('Invalid action');if(input.action==='add'&&!FOODS.some(f=>f.id===input.ingredient))throw new Error('Invalid ingredient');if(input.action==='start'){if(!$('overlay').open)throw new Error('Game is already active');closeDialog();}if(input.action==='switch_customer'){$('second-customer').click();}if(input.action==='treat'){$('kombucha').click();}if(input.action==='refill'&&!refill())throw new Error('Cannot refill now');if(input.action==='take_bread'&&!pickBread())throw new Error('Cannot take bread now');if(input.action==='add'&&!addFood(FOODS.findIndex(f=>f.id===input.ingredient)))throw new Error('Cannot add now');if(input.action==='undo'&&!removeLast())throw new Error('Nothing to undo');if(input.action==='serve'&&!deliver())return {...snapshot(),accepted:false};return snapshot();}};try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
